export * from "./prompt/config_render_registry";
export * from "./script/event_render_registry";
export * from "./shared/phase_stage_localization_registry";
export * from "./roles/permissions";
export * from "./registries/tool_spec_registry";
export * from "./registries/win_condition_registry";
export * from "./roles/contracts";
export * from "./roles/catalog";
export * from "./roles/role-catalog-assembly";
export * from "./roles/wolf_team";
export * from "./roles/inspection";
export {
  ROLE_INSPECTION_POLICY_ROLES,
  projectPairState,
  copyAbilityData,
  allNightAbilities,
  nightAbilityDisabled,
  abilityStatus,
  findNightAbility,
  activeNightAbility,
  retiredNightAbilityIds,
  projectRoleInspectionState,
  projectSeerState,
  projectWitchState,
  setNightAbilityEnabled,
  retireBorrowedNightAbility,
  expireLuckyAbilitiesOnDeath,
  setNightAbilityStartDay,
  recordNightAbilityUse,
  type NightAbility,
  type NightAbilityReadView,
} from "./roles/abilities";
export {
  bindNightAbilityActorQuery,
  createNightActorEligibilityQuery,
  createNightAbilityActorQuery,
  type NightActorEligibilityQuery,
  type NightAbilityActorQuery,
  type NightAbilityRosterPort,
} from "./roles/night-ability-actors";
export * from "./roles/ability_changes";
export * from "./roles/night-ability-grants";
export * from "./sheriff/config_normalizer";
export * from "./sheriff/election";
export * from "./sheriff/speaking_order";
export * from "./sheriff/badge";
export * from "./self_destruct/config_normalizer";
export * from "./stages/night/contracts";
export * from "./stages/night/night_stage_registry";
export * from "./validation/tool_validation_rule_registry";
export * from "./win_conditions/contracts";

/**
 * Controlled Night scenario verifies typed Awakened proposals reach actual damage settlement without runtime scopes entering summaries.
 * Input: Original local role world and controlled stage registry through the complete NightPipeline.
 * Output and oracle: Exact public summary/source results remain unchanged; the stage mocks are explicit, no new expectation or model is generated.
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../src/app/bootstrap";
import { DeathCause, Role, StatusMark, type BoardConfig } from "../../../src/core";
import { captureNightLife, type NightAwakenedEffect } from "../../../src/core/domain/night_effects";
import { DamageResolutionSystem } from "../../../src/core/domain/systems/damage_resolution_system";
import { NightPipeline } from "../../../src/game/engine/phase_pipeline/night_pipeline";
import { NightStageRegistry } from "../../../src/game/mechanisms/stages/night/night_stage_registry";
import type { NightStageHandler } from "../../../src/game/mechanisms/stages/night/contracts";
import { ToolGateway } from "../../../src/game/gateway/tool_gateway";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";

const roles = [Role.Wolf, Role.Witch, Role.Seer, Role.Guard, Role.Villager, Role.Villager];

const config: BoardConfig = {
  ...sixPlayerMvpConfig,
  roleSetups: [...new Set(roles)].map((role) => ({
    role,
    count: roles.filter((r) => r === role).length,
  })),
};

const fixture = () => bootstrapGame(config, { fixedRoles: roles });

type Game = ReturnType<typeof fixture>;

const scope = (game: Game, id: number) => captureNightLife(game.world, id)!;

const effect = (game: Game, targetId: number, isCurrent = () => true): NightAwakenedEffect => ({
  actorId: 1,
  target: scope(game, targetId),
  isCurrent,
});

test("NightPipeline delivers typed awakened proposals to Damage without exposing runtime scopes in the summary", async () => {
  const game = fixture();
  class ControlledStages extends NightStageRegistry {
    override getStages(): NightStageHandler[] {
      return [
        {
          id: "controlled_damage",
          priority: 900,
          async execute(ctx) {
            ctx.state.awakenedEffects!.shields.push(effect(game, 5));
            ctx.state.awakenedEffects!.attacks.push(effect(game, 6));
            ctx.ensureMarks(5).add(StatusMark.WolfKillMark);
          },
        },
      ];
    }
  }
  const result = await new NightPipeline({
    world: game.world,
    toolGateway: new ToolGateway(),
    damageResolutionSystem: new DamageResolutionSystem(),
    events: [],
    stageRegistry: new ControlledStages(),
  }).execute(
    config,
    {
      async getAction() {
        throw new Error("unexpected_action_request");
      },
    },
    1,
  );
  expect(result.interrupted).toBe(false);
  if (result.interrupted) throw new Error("unexpected_interruption");
  expect(result.damage).toEqual({
    deaths: [6],
    deathSources: { 6: [DeathCause.AwakenedHiddenKnife] },
  });
  expect(result.summary).toEqual({
    wolfTarget: null,
    deaths: [6],
    seerChecks: [],
    interruptedBySelfDestruct: false,
  });
  expect(JSON.stringify(result.summary)).not.toContain('"life"');
  expect(game.world.getAliveEntityIds()).toEqual([1, 2, 3, 4, 5, 6]);
});

/**
 * 咒狐场景验证完整夜提交后重入、警长时点替换过滤和个人终局。输入为原毒矩阵、固定角色和真实 Pipeline／经理；手写保留效果、独立毒结果与咒狐唯一胜者是预期，不重生成预期数据。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { Camp, COMPONENT, Role, PotionType, type RoleComponent } from "../../../../src/core";
import { foxBoard } from "../../../support/features/cursed-fox/builders/scenario";
import { DamageResolutionSystem } from "../../../../src/core/domain/systems/damage_resolution_system";
import { RoleCatalog } from "../../../../src/game/mechanisms/roles/catalog";
import {
  getDefaultRoleCatalog,
  getDefaultRoleContributions,
  createRoleCatalog,
} from "../../../../src/game/mechanisms/roles/role-catalog-assembly";
import { SEER_NIGHT_STAGES } from "../../../../src/game/mechanisms/roles/seer/night_stages";
import { NightPipeline } from "../../../../src/game/engine/phase_pipeline/night_pipeline";
import { NightStageRegistry } from "../../../../src/game/mechanisms/stages/night/night_stage_registry";
import { ToolGateway } from "../../../../src/game/gateway/tool_gateway";
import { BaselineBotActionProvider } from "../../../../src/game/drivers/privileged-baseline";

const deck = [Role.CursedFox, Role.Seer, Role.Wolf, Role.Witch, Role.Guard, Role.Villager];

const fixture = () => bootstrapGame(foxBoard(deck), { fixedRoles: deck });

test("committed Fox inspection interrupted later cannot be silently lost by full same-night reentry", async () => {
  const { world } = fixture();
  let current = true,
    requests = 0;
  const catalog = createRoleCatalog({
    contributions: getDefaultRoleContributions().map((profile) => ({
      ...profile,
      runtime: {
        ...profile.runtime,
        possibleNightAbilities: [],
        nightStages:
          profile.metadata.role === Role.Seer
            ? [
                SEER_NIGHT_STAGES[0]!,
                {
                  id: "late_interrupt",
                  priority: 800,
                  async execute() {
                    current = false;
                  },
                },
              ]
            : [],
      },
    })),
  });
  const pipeline = new NightPipeline({
    world,
    events: [],
    toolGateway: new ToolGateway(),
    damageResolutionSystem: new DamageResolutionSystem(),
    stageRegistry: new NightStageRegistry(catalog),
  });
  const actions = {
    async getAction() {
      requests++;
      return { name: "check_identity" as const, args: { target_id: 1 } };
    },
  };
  expect(await pipeline.execute(foxBoard(deck), actions, 1, { isCurrent: () => current })).toEqual({
    interrupted: true,
  });
  current = true;
  await expect(
    pipeline.execute(foxBoard(deck), actions, 1, { isCurrent: () => current }),
  ).rejects.toThrow("fox_inspection_night_reentry_after_commit");
  expect(requests).toBe(1);
});

for (const poison of [false, true])
  test(`first-day sheriff identity replacement filters only old FoxInspection; independent poison=${poison}`, async () => {
    const board = { ...foxBoard(deck), enableSheriff: true },
      game = bootstrapGame(board, { fixedRoles: deck }),
      base = new BaselineBotActionProvider(game.world);
    let replaced = false;
    await game.phaseManager.runSingleCycle(
      {
        async getAction(req) {
          if (req.allowedTools.includes("kill_vote"))
            return { name: "kill_vote", args: { target_id: null, abstain: true } };
          if (req.allowedTools.includes("check_identity"))
            return { name: "check_identity", args: { target_id: 1 } };
          if (req.allowedTools.includes("use_potion"))
            return {
              name: "use_potion",
              args: {
                target_id: poison ? 1 : 4,
                potion_type: poison ? PotionType.Poison : PotionType.None,
              },
            };
          if (req.context.stage === "sheriff_nomination" && !replaced) {
            const role = game.world.getComponent(1, COMPONENT.Role)!;
            role.role = Role.Villager;
            game.world.getComponent(1, COMPONENT.Camp)!.camp = Camp.Good;
            (role as { privateState: Readonly<Record<string, unknown>> }).privateState = {};
            replaced = true;
          }
          if (req.allowedTools.includes("vote"))
            return { name: "vote", args: { target_id: null, abstain: true } };
          return base.getAction(req);
        },
      },
      2,
    );
    expect(replaced).toBe(true);
    expect(
      game.phaseManager
        .getEvents()
        .filter((e) => e.type === "night_resolved")
        .map((e) => e.payload.deaths),
    ).toEqual([poison ? [1] : []]);
    expect(game.world.getAliveEntityIds().includes(1)).toBe(!poison);
  });

test("last Good dies while Fox survives: only Fox wins at the complete night checkpoint", async () => {
  const roles = [Role.CursedFox, Role.Wolf, Role.Villager],
    game = bootstrapGame(foxBoard(roles), { fixedRoles: roles });
  const base = new BaselineBotActionProvider(game.world);
  await game.phaseManager.runSingleCycle(
    {
      async getAction(req) {
        if (req.allowedTools.includes("kill_vote"))
          return { name: "kill_vote", args: { target_id: 3, abstain: false } };
        return base.getAction(req);
      },
    },
    2,
  );
  expect(game.phaseManager.getSnapshot().result).toMatchObject({
    winner: null,
    reason: "cursed_fox_survived_faction_elimination",
    outcome: {
      kind: "victory",
      primary: { kind: "individual", playerId: 1, winningPlayerIds: [1] },
      winningPlayerIds: [1],
    },
    decidedAt: { checkpoint: "night_settled" },
  });
  expect(game.world.getAliveEntityIds()).toEqual([1, 2]);
});

/**
 * 场景验证守墓人真实周期修订、放逐时点、共享赠予技能和完整夜的私密反馈顺序。输入为原模式／语言／目标矩阵及受控 PhaseManager 或 NightPipeline 动作；原阵营历史、顺序、终结反馈和恢复交付断言保持，不从生产输出新增期望。
 */
import {
  getDefaultRoleContributions,
  createRoleCatalog,
} from "../../../../src/game/mechanisms/roles/role-catalog-assembly";

import { renderRolePrompt } from "../../../../src/game/observation/role-presentation";
import { PotionType } from "../../../../src/core";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import {
  Camp,
  Role,
  Phase,
  COMPONENT,
  WinCondition,
  ActionWindow,
  KnightDuelWindow,
  type RoleComponent,
  type GameEvent,
  type BoardConfig,
  type ActionRequest,
} from "../../../../src/core";
import { sixPlayerMvpConfig } from "../../../../src/runtime/scenarios/six_player_mvp";
import {
  captureExileFeedback,
  GRAVEKEEPER_FEEDBACK_STAGE,
} from "../../../../src/game/mechanisms/roles/gravekeeper/feedback";
import { getGravekeeperState } from "../../../../src/game/mechanisms/roles/gravekeeper/ports";
import {
  RoleCatalog,
  getDefaultRoleCatalog,
  getDefaultToolSpecRegistry,
  getDefaultTargetHintRegistry,
  getDefaultPhaseStageLocalizationRegistry,
  getDefaultConfigRenderRegistry,
} from "../../../../src/game/mechanisms";
import { NightStageRegistry } from "../../../../src/game/mechanisms/stages/night/night_stage_registry";
import { NightPipeline } from "../../../../src/game/engine/phase_pipeline/night_pipeline";
import { DamageResolutionSystem } from "../../../../src/core/domain/systems/damage_resolution_system";
import { ToolGateway } from "../../../../src/game/gateway/tool_gateway";
import { buildAgentVisibleEventFeed } from "../../../../src/game/engine/agent_visible_event_feed";
import { PlayerPromptPolicy } from "../../../../src/ai/agents/player/player_prompt_policy";
import { getDefaultScriptEventRenderRegistry } from "../../../../src/game/mechanisms/script/event_render_registry";
import { grantNightAbility } from "../../../../src/game/mechanisms/roles/night-ability-grants";

const deck = [Role.Wolf, Role.Wolf, Role.Gravekeeper, Role.Seer, Role.Villager, Role.Villager];

const board: BoardConfig = {
  ...sixPlayerMvpConfig,
  winConditions: [WinCondition.SlaughterSide],
  roleSetups: [
    { role: Role.Wolf, count: 2 },
    { role: Role.Gravekeeper, count: 1 },
    { role: Role.Seer, count: 1 },
    { role: Role.Villager, count: 2 },
  ],
};

const role = (world: ReturnType<typeof bootstrapGame>["world"], id: number) =>
  world.getComponent(id, COMPONENT.Role)!;

const state = (world: ReturnType<typeof bootstrapGame>["world"], id = 3) =>
  getGravekeeperState(role(world, id))!;

function policy(world: ReturnType<typeof bootstrapGame>["world"], config: BoardConfig = board) {
  return new PlayerPromptPolicy(world, {
    roleCatalog: getDefaultRoleCatalog(),
    toolSpecRegistry: getDefaultToolSpecRegistry(),
    targetHintRegistry: getDefaultTargetHintRegistry(),
    phaseStageLocalizationRegistry: getDefaultPhaseStageLocalizationRegistry(),
    configRenderRegistry: getDefaultConfigRenderRegistry(),
    boardConfig: config,
  });
}

const request = (
  actorId: number,
  day: number,
  events: ActionRequest["context"]["visible_events"],
): ActionRequest => ({
  actorId,
  phase: Phase.Day,
  allowedTools: ["speak"],
  context: { day, stage: "day_speech", visible_events: events, turn_constraints: {} },
});

for (const mode of ["leave_night", "leave_and_restore", "same_phase_jump"] as const)
  test(`${mode}: phase revision interrupts the real second night before feedback, damage or subsequent turns, and a fresh run can still deliver once`, async () => {
    const game = bootstrapGame(board, { fixedRoles: deck });
    let cycle = 1,
      cancel = true;
    const provider = {
      async getAction(req: ActionRequest) {
        if (req.allowedTools.includes("speak_to_wolves"))
          return { name: "speak_to_wolves" as const, args: { text: "End", end_chat: true } };
        if (req.allowedTools.includes("kill_vote")) {
          if (cycle === 2 && cancel) {
            cancel = false;
            if (mode !== "same_phase_jump") game.phaseManager.jumpTo(Phase.Voting);
            if (mode !== "leave_night") game.phaseManager.jumpTo(Phase.Night);
            return { name: "kill_vote" as const, args: { target_id: 3, abstain: false } };
          }
          return { name: "kill_vote" as const, args: { target_id: null, abstain: true } };
        }
        if (req.allowedTools.includes("check_identity"))
          return { name: "check_identity" as const, args: { target_id: cycle === 1 ? 1 : 2 } };
        if (req.allowedTools.includes("speak"))
          return { name: "speak" as const, args: { text: "Raw" } };
        if (req.allowedTools.includes("vote"))
          return {
            name: "vote" as const,
            args: { target_id: cycle === 1 ? 1 : 2, abstain: false },
          };
        throw new Error(`unexpected:${req.context.stage}`);
      },
    };
    await game.phaseManager.runSingleCycle(provider);
    cycle = 2;
    const prefix = game.phaseManager.getEvents().length;
    const cancelled = await game.phaseManager.runSingleCycle(provider);
    expect(cancelled).toEqual({
      day: 2,
      phase: mode === "leave_night" ? Phase.Voting : Phase.Night,
      gameOver: false,
      result: null,
    });
    expect(state(game.world)).toEqual({ history: [] });
    expect(game.world.getAliveEntityIds()).toEqual([2, 3, 4, 5, 6]);
    expect(
      game.phaseManager
        .getEvents()
        .slice(prefix)
        .map((event) => event.type),
    ).not.toContain("wolf_kill_vote_cast");
    for (const type of [
      "gravekeeper_reported",
      "night_resolved",
      "seer_checked",
      "day_speech",
      "vote_cast",
    ])
      expect(
        game.phaseManager
          .getEvents()
          .slice(prefix)
          .some((event) => event.type === type),
      ).toBe(false);
    expect(cancelled).not.toHaveProperty("previousExile");
    await game.phaseManager.runSingleCycle(provider);
    expect(state(game.world).history).toEqual([
      { exileDay: 1, receivedDay: 2, targetId: 1, result: { kind: "camp", camp: "wolf" } },
    ]);
    expect(game.phaseManager.getSnapshot().result?.winner).toBe(Camp.Good);
  });

for (const mode of ["knight", "white_wolf_king"] as const)
  test(`${mode}: a public kill interrupts the day without becoming a next-night exile feedback`, async () => {
    const fixed =
      mode === "knight"
        ? [Role.Knight, Role.Wolf, Role.Gravekeeper, Role.Seer, Role.Villager, Role.Wolf]
        : [
            Role.WhiteWolfKing,
            Role.Wolf,
            Role.Gravekeeper,
            Role.Seer,
            Role.Villager,
            Role.Villager,
          ];
    const config = {
        ...board,
        roleSetups: [...new Set(fixed)].map((role) => ({
          role,
          count: fixed.filter((item) => item === role).length,
        })),
        hooks: { ...board.hooks, onPreVote: true },
        knight: { enabledWindows: [KnightDuelWindow.AfterSpeeches] },
        selfDestruct: {
          enabledWindows: mode === "white_wolf_king" ? [ActionWindow.OnPreVote] : [],
        },
      },
      game = bootstrapGame(config, { fixedRoles: fixed });
    let cycle = 1;
    const provider = {
      async getAction(req: ActionRequest) {
        if (req.allowedTools.includes("speak_to_wolves"))
          return { name: "speak_to_wolves" as const, args: { text: "End", end_chat: true } };
        if (req.allowedTools.includes("kill_vote"))
          return { name: "kill_vote" as const, args: { target_id: null, abstain: true } };
        if (req.allowedTools.includes("check_identity"))
          return {
            name: "check_identity" as const,
            args: { target_id: cycle === 1 ? 2 : mode === "knight" ? 6 : 2 },
          };
        if (req.allowedTools.includes("speak"))
          return { name: "speak" as const, args: { text: "Raw" } };
        if (req.allowedTools.includes("duel"))
          return { name: "duel" as const, args: { target_id: 2, confirm: true } };
        if (req.allowedTools.includes("self_destruct_with_target"))
          return {
            name: "self_destruct_with_target" as const,
            args: { target_id: 5, confirm: true, reason: "Public blast" },
          };
        if (req.allowedTools.includes("self_destruct")) return null;
        if (req.allowedTools.includes("vote"))
          return {
            name: "vote" as const,
            args: { target_id: mode === "knight" ? 6 : 2, abstain: false },
          };
        throw new Error(`unexpected:${req.context.stage}`);
      },
    };
    await game.phaseManager.runSingleCycle(provider);
    cycle = 2;
    await game.phaseManager.runSingleCycle(provider);
    expect(
      game.phaseManager.getEvents().some((event) => event.type === "gravekeeper_reported"),
    ).toBe(false);
    expect(state(game.world)).toEqual({ history: [] });
    expect(game.phaseManager.getSnapshot().result?.winner).toBe(Camp.Good);
  });

for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: frozen camp labels are delivered after Witch/before Seer, remain actor-private and expose no pending fact or exact role`, async () => {
    const config = {
        ...board,
        roleSetups: [
          { role: Role.Wolf, count: 2 },
          { role: Role.Gravekeeper, count: 1 },
          { role: Role.Seer, count: 1 },
          { role: Role.Witch, count: 1 },
          { role: Role.Villager, count: 1 },
        ],
      },
      { world } = bootstrapGame(config, {
        fixedRoles: [Role.Wolf, Role.Wolf, Role.Gravekeeper, Role.Seer, Role.Witch, Role.Villager],
        locale,
      }),
      events: GameEvent[] = [];
    const catalog = createRoleCatalog({
      contributions: getDefaultRoleContributions().map((profile) =>
        profile.metadata.role === Role.Wolf
          ? { ...profile, runtime: { ...profile.runtime, inspectionLabels: { camp: Camp.Good } } }
          : profile,
      ),
    });
    const fact = captureExileFeedback(world, 1, 1, catalog)!;
    expect(fact).toEqual({ exileDay: 1, targetId: 1, result: { kind: "camp", camp: "good" } });
    world.getComponent(1, COMPONENT.Camp)!.camp = Camp.ThirdParty;
    world.getComponent(1, COMPONENT.Alive)!.alive = false;
    expect(state(world)).toEqual({ history: [] });
    expect(policy(world).buildObservation(request(3, 1, [])).ownState.gravekeeper).toEqual({
      history: [],
    });
    const stages = new NightStageRegistry();
    expect(stages.getStages(board).map((stage) => stage.id)).toContain("gravekeeper_feedback");
    const executionOrder: string[] = [];
    const instrumented = createRoleCatalog({
      contributions: getDefaultRoleContributions().map((profile) =>
        profile.metadata.role !== Role.Gravekeeper
          ? profile
          : {
              ...profile,
              runtime: {
                ...profile.runtime,
                nightStages: [
                  {
                    ...GRAVEKEEPER_FEEDBACK_STAGE,
                    async execute(ctx) {
                      executionOrder.push("feedback");
                      await GRAVEKEEPER_FEEDBACK_STAGE.execute(ctx);
                    },
                  },
                ],
              },
            },
      ),
    });
    const pipeline = new NightPipeline({
      world,
      events,
      toolGateway: new ToolGateway(),
      damageResolutionSystem: new DamageResolutionSystem(),
      stageRegistry: new NightStageRegistry(instrumented),
    });
    await pipeline.execute(
      config,
      {
        async getAction(req) {
          executionOrder.push(req.context.stage);
          if (req.allowedTools.includes("speak_to_wolves"))
            return { name: "speak_to_wolves", args: { text: "End", end_chat: true } };
          if (req.allowedTools.includes("kill_vote"))
            return { name: "kill_vote", args: { target_id: null, abstain: true } };
          if (req.allowedTools.includes("use_potion"))
            return { name: "use_potion", args: { target_id: 5, potion_type: PotionType.None } };
          if (req.allowedTools.includes("check_identity"))
            return { name: "check_identity", args: { target_id: 2 } };
          throw new Error("no_gravekeeper_action");
        },
      },
      2,
      { previousExile: fact },
    );
    expect(executionOrder.indexOf("witch")).toBeLessThan(executionOrder.indexOf("feedback"));
    expect(executionOrder.indexOf("feedback")).toBeLessThan(executionOrder.indexOf("seer"));
    const report = events.find((event) => event.type === "gravekeeper_reported")!;
    expect(report.payload).toEqual({
      actorId: 3,
      targetId: 1,
      exileDay: 1,
      receivedDay: 2,
      result: { kind: "camp", camp: "good" },
    });
    expect(state(world).history).toEqual([
      { targetId: 1, exileDay: 1, receivedDay: 2, result: { kind: "camp", camp: "good" } },
    ]);
    expect(state(world).history[0].result).not.toBe(report.payload.result);
    expect(state(world).history[0].result).not.toBe(fact.result);
    for (const actorId of world.entityIds())
      expect(
        buildAgentVisibleEventFeed(world, events, actorId).some(
          (event) => event.type === "gravekeeper_reported",
        ),
